s_in_n = np.zeros(NL)
np.add.at(s_in_n, csr_rows, jv_abs_an)
s_tot = s_out_n + s_in_n
s_safe = np.where(s_tot > 0, s_tot, 1.0)
jv_crofts = jv_abs_an / np.sqrt(s_safe[csr_rows] * s_safe[csr_cols])
